const App: Component = () => {
  const [track, { isLoading }] = useTrackInfo()

  return (
    <Base>
      <Show when={!isLoading()} fallback={<Spinner />}>
        <AlbumInfo track={track() as ITrack} />
      </Show>
    </Base>
  )
}

const useTrackInfo = (): [Accessor<ITrack | null>, { isLoading: Accessor<boolean> }] => {
  const [track, setTrack] = createSignal<ITrack | null>(null)
  const [isLoading, setIsLoading] = createSignal<boolean>(true)

  window.spotifyApi.getCurrentTrack((_, data) => {
    setTrack(data)
    setIsLoading(false)
  })

  return [track, { isLoading }]
}

const Button: Component<IButton> = (props) => {
  const [local, rest] = splitProps(props, ['tooltip', 'id'])

  const SVG = svgMap[local.id]
  return (
    <Tooltip tip={local.tooltip}>
      <ButtonWrapper {...rest}>
        <SVG class={classNames({ flipped: props.id === 'next' })} />
      </ButtonWrapper>
    </Tooltip>
  )
}

